import { describe, expect, it } from "vitest";
import { UtteranceType, type Conversation, type UnionEventType, type Utterance } from "../../types";
import { resolveTriggeringMessage } from "./resolveTriggeringMessage";

function userUtterance(text: string, originalTimestamp: number): Utterance {
  return {
    __typename: "Utterance",
    id: `u-${originalTimestamp}`,
    metadata: { parseData: {} },
    rephrase: false,
    rephrasePrompt: null,
    text,
    timestamp: new Date(originalTimestamp * 1000).toISOString(),
    tokens: [],
    type: UtteranceType.User,
    originalTimestamp,
  };
}

function botUtterance(text: string, originalTimestamp: number): Utterance {
  return { ...userUtterance(text, originalTimestamp), type: UtteranceType.Bot };
}

function conversations(...events: UnionEventType[]): Conversation[] {
  return [{ id: "c1", events } as Conversation];
}

describe("resolveTriggeringMessage", () => {
  it("returns the text of the user utterance whose originalTimestamp matches", () => {
    const list = conversations(
      userUtterance("first", 10),
      userUtterance("triggered me", 42),
      userUtterance("later", 99),
    );
    expect(resolveTriggeringMessage(list, 42)).toBe("triggered me");
  });

  it("returns undefined when the timestamp is not stamped", () => {
    const list = conversations(userUtterance("hi", 42));
    expect(resolveTriggeringMessage(list, undefined)).toBeUndefined();
  });

  it("returns undefined when no user utterance matches the timestamp", () => {
    const list = conversations(userUtterance("hi", 42));
    expect(resolveTriggeringMessage(list, 7)).toBeUndefined();
  });

  it("ignores a bot utterance that shares the timestamp", () => {
    const list = conversations(botUtterance("bot said this", 42));
    expect(resolveTriggeringMessage(list, 42)).toBeUndefined();
  });

  it("searches across multiple conversations", () => {
    const list: Conversation[] = [
      { id: "c1", events: [userUtterance("old", 1)] } as Conversation,
      { id: "c2", events: [userUtterance("match", 42)] } as Conversation,
    ];
    expect(resolveTriggeringMessage(list, 42)).toBe("match");
  });
});
